// ignore_for_file: prefer_initializing_formals

/// Session ownership lease (#428): a `_owner.json` sidecar next to the
/// session JSONL marks the ONE process driving the session. Every other
/// opener becomes a VIEWER — a viewer never seizes a live lease (Rev-2
/// owner ruling); the lease changes hands only by graceful release
/// (owner deletes the sidecar) or stale expiry (owner died, ~15s).
///
/// Layout: session files live at
/// `<sessionsRoot>/<encoded-cwd>/<timestamp>_<sessionId>.jsonl`; the
/// sidecar sits next to the file as `<timestamp>_<sessionId>.owner.json`
/// and carries the `sessionId` inside, so a project directory holding
/// many sessions leases each independently. Like the `.presence/` store,
/// staleness is judged on the LOCAL clock against the sidecar's file
/// mtime — the write clock of the filesystem, immune to cross-host
/// wall-clock skew (E1).
library;

import 'dart:convert';
import 'dart:math';

import '../../env/execution_env.dart';

/// One ownership lease: who drives a session, since when, last seen when.
final class SessionLease {
  /// Parses strictness: [fromJson] throws [FormatException] on a missing
  /// or mistyped required field (the sidecar is then treated as no lease
  /// — E4 fail-open — by the store); unknown fields are tolerated and
  /// reported in [unknownFieldNotes].
  SessionLease({
    required this.host,
    required this.sessionId,
    required this.pid,
    required this.bootId,
    required this.heartbeatAt,
    required this.acquiredAt,
    this.sessionName,
    this.unknownFieldNotes = const [],
  });

  /// The owning surface kind: `cli`, `macos`, `ios`, `extension`.
  final String host;

  /// The leased session id (the sidecar's key content — the file name is
  /// derived from the session file, the identity from here).
  final String sessionId;

  /// The owning process id (diagnostics + banner).
  final int pid;

  /// Random per-process-start id: a recycled PID from a previous boot
  /// never matches (E3).
  final String bootId;

  /// When the owner last proved liveness (UTC ISO 8601).
  final String heartbeatAt;

  /// When the lease was taken (UTC ISO 8601; the banner's "since").
  final String acquiredAt;

  /// The session's display name, when known (banner friendliness).
  final String? sessionName;

  /// One note per JSON field the parser did not know (tolerated with a
  /// note, never a refusal — older/newer writers interoperate).
  final List<String> unknownFieldNotes;

  static const _knownFields = {
    'host',
    'sessionId',
    'pid',
    'bootId',
    'sessionName',
    'heartbeatAt',
    'acquiredAt',
  };

  Map<String, dynamic> toJson() => {
    'host': host,
    'sessionId': sessionId,
    'pid': pid,
    'bootId': bootId,
    if (sessionName != null) 'sessionName': sessionName,
    'heartbeatAt': heartbeatAt,
    'acquiredAt': acquiredAt,
  };

  factory SessionLease.fromJson(Map<String, dynamic> json) {
    String requiredString(String key) {
      final value = json[key];
      if (value is String && value.isNotEmpty) return value;
      throw FormatException('lease field "$key" missing or not a string');
    }

    final pid = json['pid'];
    if (pid is! int) {
      throw FormatException('lease field "pid" missing or not an int');
    }
    final notes = [
      for (final key in json.keys)
        if (!_knownFields.contains(key)) 'unknown lease field "$key"',
    ];
    return SessionLease(
      host: requiredString('host'),
      sessionId: requiredString('sessionId'),
      pid: pid,
      bootId: requiredString('bootId'),
      heartbeatAt: requiredString('heartbeatAt'),
      acquiredAt: requiredString('acquiredAt'),
      sessionName: json['sessionName'] as String?,
      unknownFieldNotes: List.unmodifiable(notes),
    );
  }
}

/// The lease state a drive-open finds on disk.
final class LeaseInspect {
  const LeaseInspect._(this.state, this.lease);

  /// No sidecar on disk: the lease is free.
  factory LeaseInspect.free() => LeaseInspect._(LeaseState.free, null);

  /// A live lease held by [lease]: openers are viewers.
  factory LeaseInspect.live(SessionLease lease) =>
      LeaseInspect._(LeaseState.live, lease);

  /// An expired lease of a dead owner ([lease]) — free to take fresh.
  factory LeaseInspect.expired(SessionLease lease) =>
      LeaseInspect._(LeaseState.expired, lease);

  /// The classification of the sidecar that was read.
  final LeaseState state;

  /// The lease record when one exists on disk (live or expired), else
  /// null. An expired lease is surfaced so the acquirer can warn naming
  /// the dead owner.
  final SessionLease? lease;
}

/// The outcome states of [FileSessionLeaseStore.inspect].
enum LeaseState {
  /// No sidecar on disk (or an unreadable one): the lease is free.
  free,

  /// A live lease: heartbeat fresher than the staleness window. The
  /// opener becomes a viewer — no path seizes a live lease.
  live,

  /// The sidecar exists but its heartbeat is older than the window: the
  /// owner is dead (crash, kill -9, suspended past the window). The
  /// lease is simply free — the next drive-open acquires it fresh.
  expired,
}

/// The outcome of [FileSessionLeaseStore.acquire].
sealed class LeaseAcquire {
  const LeaseAcquire();
}

/// This process now owns the session: heartbeat + release with [bootId].
final class LeaseAcquired extends LeaseAcquire {
  const LeaseAcquired(this.lease, {this.replaced});

  /// The fresh lease as written (acquiredAt == heartbeatAt == now).
  final SessionLease lease;

  /// The dead owner's expired lease this acquire overwrote, if any —
  /// the caller prints the dead-owner warning naming host + pid.
  final SessionLease? replaced;
}

/// A live lease blocked the drive-open: this opener is a VIEWER. No
/// takeover exists — the viewer messages the owner through the fabric.
final class LeaseBlocked extends LeaseAcquire {
  const LeaseBlocked(this.lease);

  /// The owner's live lease (banner material).
  final SessionLease lease;
}

/// This process opened for drive, but the lease could not be enforced
/// because the backend has NO atomic rename (E5, pure web stores): the
/// drive proceeds WITHOUT a lease — the only remaining fail-open. On
/// backends that CAN publish atomically, a write/rename/verify failure
/// is a [LeaseRefused] (#2138) — never a silent second writer.
final class LeaseUnenforced extends LeaseAcquire {
  const LeaseUnenforced(this.lease);

  /// The lease as attempted (not on disk).
  final SessionLease lease;
}

/// Why an enforceable backend refused to prove the session free (#2138).
enum LeaseRefuseReason {
  /// The temp-write or atomic rename failed: no ownership sidecar was
  /// published, so a live owner cannot be ruled out.
  publishFailed,

  /// The atomic publish succeeded but the ownership verify re-read kept
  /// failing: the store cannot prove whose sidecar is on disk.
  verifyFailed,
}

/// The store could not PROVE the session is free on an enforceable
/// backend (#2138): the caller must NOT drive — a failed open is
/// recoverable, a two-writer session is corruption. Stand down to the
/// attach surface or refuse with a clear message.
final class LeaseRefused extends LeaseAcquire {
  const LeaseRefused(this.reason);

  /// Which enforcement leg failed.
  final LeaseRefuseReason reason;
}

/// The verdict of one [FileSessionLeaseStore.heartbeat] beat (#2257).
/// The beat distinguishes a refreshed lease from a LOST one and from an
/// IO hiccup: a transient sidecar read/write failure never refutes
/// ownership — only a readable foreign claim, or a verified-absent
/// sidecar, does.
sealed class LeaseBeat {
  const LeaseBeat();
}

/// The sidecar was refreshed (and on the E5 fallback verified) ours:
/// ownership stands.
final class LeaseBeatRenewed extends LeaseBeat {
  const LeaseBeatRenewed();
}

/// The sidecar could not be read or written this beat (#2257): an IO
/// hiccup, not a loss — ownership is KEPT and the next beat retries.
/// [error] carries the raw fs failure so the caller can alarm when the
/// failure persists (AC2).
final class LeaseBeatIoFailed extends LeaseBeat {
  const LeaseBeatIoFailed(this.error);

  /// The raw filesystem failure behind the hiccup.
  final FileError error;
}

/// The sidecar is readable and names ANOTHER bootId, or is verifiably
/// gone (a deletion is not transient — a rival may acquire at any
/// moment): the lease is lost, the caller must demote (AC3).
final class LeaseBeatLost extends LeaseBeat {
  const LeaseBeatLost(this.lease);

  /// The foreign lease that refuted us; null when the sidecar is absent.
  final SessionLease? lease;
}

/// File-backed ownership lease over an [ExecutionEnv]: the `_owner.json`
/// sidecar next to the session JSONL. READ-side failures stay fail-open
/// (E4): a lease that cannot be read is no lease; nothing here ever
/// blocks opening a session for reading. The DRIVE-side acquire is the
/// opposite (since #2138): on a backend that can publish atomically, a
/// publish/verify failure REFUSES the drive ([LeaseRefused]) — a failed
/// open is recoverable, a two-writer session is corruption. Only a
/// backend with no atomic rename (E5, web) stays fail-open
/// ([LeaseUnenforced]).
final class FileSessionLeaseStore {
  /// Creates the store. [now] and [staleAfter] are injectable for tests;
  /// the heartbeat cadence lives with the owners (CLI ~4s on the inbox
  /// tick, app 5s timer) — the store only judges staleness.
  FileSessionLeaseStore({
    required ExecutionEnv env,
    DateTime Function()? now,
    this.staleAfter = const Duration(seconds: 15),
  }) : _env = env,
       _now = now ?? DateTime.now;

  final ExecutionEnv _env;
  final DateTime Function() _now;

  /// How old a lease's last heartbeat may be before its owner is dead.
  final Duration staleAfter;

  /// The atomic-publish capability of the backend, or null when the env
  /// cannot rename (E5, pure web): every sidecar write routes through
  /// tmp + rename when non-null (#2262).
  RenamableFileSystem? get _renamable =>
      _env is RenamableFileSystem ? _env as RenamableFileSystem : null;

  /// How many times the post-publish verify re-read may fail before the
  /// acquire is refused (#2138): a transient read hiccup heals inside the
  /// bound, a persistent outage cannot prove ownership.
  static const _verifyReadAttempts = 3;

  /// How many times [FileSessionLeaseStore.inspect] re-reads an
  /// undecodable sidecar before the documented E4 fail-open applies
  /// (#2262): a read caught mid-write of a non-atomic writer holds torn
  /// bytes for milliseconds only, while a genuinely corrupt file stays
  /// undecodable through the bound.
  static const _tornReadAttempts = 3;

  /// Pause between [FileSessionLeaseStore.inspect] torn-read retries: the
  /// tear window of a real writer is far below one heartbeat, so even the
  /// corrupt-forever worst case keeps inspect latency negligible.
  static const _tornReadDelay = Duration(milliseconds: 2);

  /// How many times [FileSessionLeaseStore.heartbeat] re-reads the
  /// sidecar on a read hiccup before classifying the beat (#2257): a
  /// transient fs error heals inside the bound and never refutes
  /// ownership; `notFound` short-circuits — a missing sidecar is a
  /// deletion, not a hiccup.
  static const _heartbeatReadAttempts = 3;

  /// The sidecar path for a session JSONL path:
  /// `<timestamp>_<sessionId>.jsonl` → `<timestamp>_<sessionId>.owner.json`.
  String sidecarPath(String sessionFilePath) =>
      sessionFilePath.replaceAll(RegExp(r'\.jsonl$'), '.owner.json');

  /// A random per-process boot id (E3: recycles PIDs never match).
  static String newBootId() {
    final random = Random();
    final micros = DateTime.now().toUtc().microsecondsSinceEpoch;
    // dart2js: shifts are 32-bit — `1 << 32` == 0, so nextInt(0) would throw
    // on web (issue #1074). Spell the bound literally.
    return '$micros-${random.nextInt(0xFFFFFFFF).toRadixString(36)}';
  }

  /// Reads and classifies the current lease for [sessionFilePath].
  /// A sidecar caught TORN mid-write (a non-atomic writer rewriting it)
  /// is retried briefly instead of failing open — an instant `free` on a
  /// live owner publishes a second owner (#2262). Still undecodable after
  /// the bound → corrupt → free (E4, with the file simply overwritten by
  /// the next acquire).
  Future<LeaseInspect> inspect(String sessionFilePath) async {
    final path = sidecarPath(sessionFilePath);
    SessionLease? lease;
    for (var attempt = 0; attempt < _tornReadAttempts; attempt++) {
      if (attempt > 0) await Future<void>.delayed(_tornReadDelay);
      final raw = (await _env.readTextFile(path)).valueOrNull;
      if (raw == null) return LeaseInspect.free();
      lease = _parseLease(raw);
      if (lease != null) break;
    }
    if (lease == null) return LeaseInspect.free();
    // Staleness on the sidecar's mtime vs the reader clock (E1): the
    // filesystem's write clock is the one clock every host on the fabric
    // shares. The injectable [now] stands in for it in tests
    // ([MemoryExecutionEnv.setMtime] moves the file side too).
    final info = (await _env.fileInfo(
      sidecarPath(sessionFilePath),
    )).valueOrNull;
    final mtimeMs = info?.mtimeMs;
    if (mtimeMs == null) return LeaseInspect.free();
    final age = _now().millisecondsSinceEpoch - mtimeMs;
    if (age >= staleAfter.inMilliseconds) {
      return LeaseInspect.expired(lease);
    }
    return LeaseInspect.live(lease);
  }

  /// Attempts to acquire the lease for a drive-open. A live lease is
  /// never seized — the caller becomes a viewer ([LeaseBlocked]). A free
  /// or expired lease is (re-)acquired atomically (temp + rename, E5);
  /// the write is verified by re-reading: a racer that renamed last owns
  /// it, the loser sees a foreign bootId and stands down. On an
  /// enforceable backend a publish or verify failure REFUSES the drive
  /// ([LeaseRefused], bounded verify retries); on a no-rename backend the
  /// drive proceeds unleased ([LeaseUnenforced], E5).
  Future<LeaseAcquire> acquire({
    required String sessionFilePath,
    required String sessionId,
    required String host,
    required String bootId,
    required int pid,
    String? sessionName,
  }) async {
    final found = await inspect(sessionFilePath);
    if (found.state == LeaseState.live) return LeaseBlocked(found.lease!);
    final nowIso = _now().toUtc().toIso8601String();
    final lease = SessionLease(
      host: host,
      sessionId: sessionId,
      pid: pid,
      bootId: bootId,
      sessionName: sessionName,
      heartbeatAt: nowIso,
      acquiredAt: nowIso,
    );
    final path = sidecarPath(sessionFilePath);
    final renamable = _renamable;
    if (renamable == null) {
      // No atomic rename on this backend (pure web stores): ownership
      // cannot be enforced safely — drive unleased rather than publish a
      // sidecar a concurrent reader could see half-written (E5).
      return LeaseUnenforced(lease);
    }
    // Atomic publish (E5): a unique temp per attempt, then one rename.
    // ponytail: rename-over leaves a microsecond double-claim window
    // (A publishes, B overwrites before A re-reads); the 5s heartbeat +
    // 15s staleness make it self-healing — a real fight shows up as both
    // sides heartbeating and needs a compare-and-swap primitive in
    // ExecutionEnv first.
    final tmp = _tmpPath(path, bootId);
    final encoded = const JsonEncoder.withIndent('  ').convert(lease.toJson());
    final write = await _env.writeFile(tmp, encoded);
    final renamed = write.isOk ? await renamable.renamePath(tmp, path) : write;
    if (renamed.isErr) {
      await _env.remove(tmp, force: true);
      // #2138 (hole-2): the backend CAN enforce (atomic publish exists)
      // but the publish failed — the store cannot prove the session is
      // free, so a second writer may be live. Refuse the drive: a failed
      // open is recoverable, a two-writer session is corruption.
      return LeaseRefused(LeaseRefuseReason.publishFailed);
    }
    // Verify ownership: the freshest rename wins; a loser stands down.
    // #2138 (hole-3): a hiccup in the verify re-read retries a bounded
    // few times; if it keeps failing — with the publish SUCCEEDED, so the
    // store demonstrably works — the store cannot prove whose sidecar is
    // on disk and the drive is refused, never fail-opened.
    SessionLease? verify;
    for (var attempt = 0; attempt < _verifyReadAttempts; attempt++) {
      verify = await _readLease(path);
      if (verify != null) break;
    }
    if (verify == null) return LeaseRefused(LeaseRefuseReason.verifyFailed);
    if (verify.bootId != bootId) return LeaseBlocked(verify);
    // We own it: sweep orphan temps of dead publishers (a crash between
    // tmp write and rename leaves one behind — cleaned on next boot,
    // #2262). Best-effort, after ownership is proven.
    await _sweepOrphanTmps(path);
    return LeaseAcquired(verify, replaced: found.lease);
  }

  /// Refreshes the heartbeat of OUR lease (#2257): the verdict tells the
  /// caller whether ownership STANDS. Only a readable foreign bootId — or
  /// a verified-absent sidecar — is a [LeaseBeatLost] (the caller must
  /// demote); a read/write IO hiccup is a [LeaseBeatIoFailed]: ownership
  /// is kept and the next beat retries, never demoted on a fs hiccup.
  ///
  /// The rewrite is ATOMIC (tmp + rename, same as acquire, #2262): the
  /// beat fires every ~4s — a far larger reader-exposure window than
  /// acquire — and a torn read of the sidecar fail-opens inspect to
  /// `free`, publishing a second owner. On a backend without rename the
  /// beat degrades to a single write + post-write verify (documented,
  /// E5): acquire never publishes a sidecar on such backends
  /// ([LeaseUnenforced]), so there is nothing to tear in normal flow.
  Future<LeaseBeat> heartbeat(String sessionFilePath, String bootId) async {
    final path = sidecarPath(sessionFilePath);
    final (lease, terminal) = await _readForBeat(path);
    if (terminal != null) return terminal;
    if (lease!.bootId != bootId) return LeaseBeatLost(lease);
    final refreshed = SessionLease(
      host: lease.host,
      sessionId: lease.sessionId,
      pid: lease.pid,
      bootId: lease.bootId,
      sessionName: lease.sessionName,
      heartbeatAt: _now().toUtc().toIso8601String(),
      acquiredAt: lease.acquiredAt,
      unknownFieldNotes: lease.unknownFieldNotes,
    );
    final encoded = const JsonEncoder.withIndent(
      '  ',
    ).convert(refreshed.toJson());
    final renamable = _renamable;
    if (renamable == null) return _refreshUnenforced(path, bootId, encoded);
    return _refreshAtomic(path, bootId, encoded, renamable);
  }

  /// The read half of a beat (#2257): returns the parsed sidecar record,
  /// or a TERMINAL beat when the read itself decides the verdict — a
  /// verified-absent sidecar is a loss (a deletion is not transient; a
  /// rival may acquire at any moment), a persistent read failure is an
  /// IO hiccup (ownership kept). A torn/corrupt body retries inside the
  /// bound; a readable record returns early.
  Future<(SessionLease?, LeaseBeat?)> _readForBeat(String path) async {
    SessionLease? lease;
    FileError? readError;
    for (var attempt = 0; attempt < _heartbeatReadAttempts; attempt++) {
      if (attempt > 0) await Future<void>.delayed(_tornReadDelay);
      final raw = await _env.readTextFile(path);
      final error = raw.errorOrNull;
      if (error != null) {
        if (error.code == FileErrorCode.notFound) {
          return (null, const LeaseBeatLost(null));
        }
        readError = error;
        continue;
      }
      lease = _parseLease(raw.valueOrNull!);
      if (lease != null) return (lease, null);
      readError = FileError(
        FileErrorCode.unknown,
        'sidecar torn or corrupt',
        path: path,
      );
    }
    return (null, LeaseBeatIoFailed(readError!));
  }

  /// The atomic-publish refresh (tmp + rename, #2262): the beat fires
  /// every ~4s — a far larger reader-exposure window than acquire — and
  /// a torn read of the sidecar fail-opens inspect to `free`, publishing
  /// a second owner. A failed publish classifies by re-reading (#2257).
  Future<LeaseBeat> _refreshAtomic(
    String path,
    String bootId,
    String encoded,
    RenamableFileSystem renamable,
  ) async {
    final tmp = _tmpPath(path, bootId);
    final write = await _env.writeFile(tmp, encoded);
    final renamed = write.isOk ? await renamable.renamePath(tmp, path) : write;
    if (renamed.isErr) {
      await _env.remove(tmp, force: true);
      return _lostOrHiccup(path, bootId, renamed.errorOrNull!);
    }
    return const LeaseBeatRenewed();
  }

  /// The E5 fallback refresh (no atomic rename; documented): a single
  /// write, then prove it landed by re-reading — never report a beat we
  /// cannot verify on disk. Written-but-unprovable is an IO anomaly
  /// (#2257), a readable foreign bootId a loss.
  Future<LeaseBeat> _refreshUnenforced(
    String path,
    String bootId,
    String encoded,
  ) async {
    final write = await _env.writeFile(path, encoded);
    if (write.isErr) return _lostOrHiccup(path, bootId, write.errorOrNull!);
    final (verified, verifyError) = await _readBeat(path);
    if (verified != null) {
      return verified.bootId == bootId
          ? const LeaseBeatRenewed()
          : LeaseBeatLost(verified);
    }
    return LeaseBeatIoFailed(
      verifyError ??
          FileError(FileErrorCode.unknown, 'sidecar unreadable', path: path),
    );
  }

  /// Classifies a beat whose refresh did NOT land (write/rename failed):
  /// the sidecar as it sits on disk decides — a readable foreign claim
  /// (or a verified absence) is a loss; our own record (or unreadable
  /// bytes) means ownership stands and only the refresh hiccupped.
  Future<LeaseBeat> _lostOrHiccup(
    String path,
    String bootId,
    FileError ioError,
  ) async {
    final (onDisk, readError) = await _readBeat(path);
    if (onDisk != null) {
      return onDisk.bootId == bootId
          ? LeaseBeatIoFailed(ioError)
          : LeaseBeatLost(onDisk);
    }
    if (readError?.code == FileErrorCode.notFound) {
      return const LeaseBeatLost(null);
    }
    return LeaseBeatIoFailed(readError ?? ioError);
  }

  /// One sidecar read for beat classification: the parsed lease, or the
  /// raw read error (null when the body was torn/corrupt).
  Future<(SessionLease?, FileError?)> _readBeat(String path) async {
    final raw = await _env.readTextFile(path);
    return switch (raw) {
      Ok(:final value) => (_parseLease(value), null),
      Err(:final error) => (null, error),
    };
  }

  /// Graceful release: the sidecar is deleted — only when it is still
  /// OURS (a viewer exiting never deletes the owner's lease).
  Future<void> release(String sessionFilePath, String bootId) async {
    final path = sidecarPath(sessionFilePath);
    final lease = await _readLease(path);
    if (lease == null || lease.bootId != bootId) return;
    await _env.remove(path, force: true);
  }

  /// The per-boot temp file an atomic sidecar publish goes through
  /// (write tmp → one rename): the bootId hash namespaces concurrent
  /// publishers and marks orphans for [_sweepOrphanTmps].
  String _tmpPath(String path, String bootId) =>
      '$path.${bootId.hashCode.toRadixString(36)}.tmp';

  /// Best-effort sweep of orphan publish temps of DEAD publishers
  /// (#2262 border case): a process crashed between tmp write and rename
  /// leaves `<sidecar>.<bootIdHash>.tmp` behind. The name carries the
  /// creator's bootId hash, so any such temp older than [staleAfter]
  /// belonged to a dead process — an in-flight acquirer's temp is
  /// milliseconds old and survives.
  Future<void> _sweepOrphanTmps(String path) async {
    final slash = path.lastIndexOf('/');
    final dir = slash < 0
        ? '.'
        : slash == 0
        ? '/'
        : path.substring(0, slash);
    final base = slash < 0 ? path : path.substring(slash + 1);
    final listing = (await _env.listDir(dir)).valueOrNull;
    if (listing == null) return;
    final cutoff = _now().millisecondsSinceEpoch - staleAfter.inMilliseconds;
    for (final entry in listing) {
      if (!entry.name.startsWith('$base.') || !entry.name.endsWith('.tmp')) {
        continue;
      }
      if (entry.mtimeMs < cutoff) {
        await _env.remove(entry.path, force: true);
      }
    }
  }

  Future<SessionLease?> _readLease(String path) async {
    final raw = (await _env.readTextFile(path)).valueOrNull;
    if (raw == null) return null;
    return _parseLease(raw);
  }

  /// Decodes a sidecar body; null when torn/corrupt (no lease).
  SessionLease? _parseLease(String raw) {
    try {
      final decoded = jsonDecode(raw);
      if (decoded is! Map<String, dynamic>) return null;
      return SessionLease.fromJson(decoded);
    } on Object {
      return null;
    }
  }
}

/// Human label for a lease host in banners: `cli` → `fa CLI`,
/// app surfaces → `Fa.app`, else the raw kind.
String leaseOwnerLabel(String host) => switch (host) {
  'cli' => 'fa CLI',
  'app' || 'macos' || 'ios' || 'android' => 'Fa.app',
  'extension' => 'Fa extension',
  final other => other,
};

/// The viewer banner (AC3/AC9). Live:
/// `Driven by fa CLI (pid 85634) since 14:32 — you are viewing. Your
/// messages are delivered to the live agent.`
/// Stale (owner's heartbeat expired while we watch):
/// the same provenance plus the reopen hint — a viewer still never
/// drives; the reopen is a fresh drive-open of a free lease.
String viewerBannerText(SessionLease lease, {required bool stale}) {
  final since = DateTime.tryParse(lease.acquiredAt)?.toLocal();
  final clock = since == null
      ? '?'
      : '${since.hour.toString().padLeft(2, '0')}:'
            '${since.minute.toString().padLeft(2, '0')}';
  final head =
      'Driven by ${leaseOwnerLabel(lease.host)} (pid ${lease.pid}) '
      'since $clock';
  return stale
      ? '$head — the owner looks gone (stale). Close and reopen this '
            'session to drive it; your messages still go to its inbox.'
      : '$head — you are viewing. Your messages are delivered to the '
            'live agent.';
}

/// Session-ownership lease + viewer mode for the CLI (#428): a drive-open
/// claims the session's `_owner.json` lease through [FileSessionLeaseStore];
/// a live lease is NEVER seized — the opener becomes a viewer that watches
/// the transcript and forwards composed input to the owner's mailbox
/// through the messaging fabric. Graceful exit releases; staleness frees.
part of 'agent_cli.dart';

/// One viewer attachment: this process opened a session whose ownership
/// lease is live. No takeover exists, so this instance only watches the
/// transcript tail and hands composer input to the owner.
final class _ViewerAttachment {
  _ViewerAttachment({
    required this.sessionId,
    required this.sessionPath,
    required this.lease,
    required this.inputChannel,
    required this.eventSource,
  });

  /// The watched session.
  final String sessionId;
  final String sessionPath;

  /// The live lease that blocked the drive — the owner's identity for
  /// the banner, refreshed when the lease flips stale.
  SessionLease lease;

  final FileSessionInputChannel inputChannel;
  final SessionEventSource eventSource;
  StreamSubscription<AttachedSessionEvent>? subscription;

  /// Whether the pre-open backlog has been printed already.
  bool sawBacklog = false;

  /// Whether the lease has gone stale since the last tick — drives the
  /// banner variant and the one-time "owner looks dead" notice.
  bool stale = false;

  Future<void> dispose() async {
    await subscription?.cancel();
    await eventSource.dispose();
  }
}

/// Transcript rows printed from the backlog before live tailing starts.
const int _viewerBacklogCap = 5;

/// The headless/wire-serve lease claim outcome (#428 + #2138).
sealed class HeadlessLeaseClaim {
  const HeadlessLeaseClaim();
}

/// The lease is ours — the run/serve drives.
final class HeadlessLeaseClaimAcquired extends HeadlessLeaseClaim {
  const HeadlessLeaseClaimAcquired();
}

/// A live owner blocked the claim: banner + exit 3 (never a second
/// writer).
final class HeadlessLeaseClaimBlocked extends HeadlessLeaseClaim {
  const HeadlessLeaseClaimBlocked(this.lease);

  /// The owner's live lease (banner material).
  final SessionLease lease;
}

/// The store could not prove the session free on an enforceable backend:
/// loud note + exit 4 (#2138) — never a crash-handler escape, never an
/// unleased drive.
final class HeadlessLeaseClaimRefused extends HeadlessLeaseClaim {
  const HeadlessLeaseClaimRefused(this.reason);

  /// Which enforcement leg failed.
  final LeaseRefuseReason reason;
}

/// AgentCli lease/viewer half (private members of the CLI library).
extension AgentCliLease on AgentCli {
  /// Claims the ownership lease for the CURRENT session after a
  /// drive-open. Free/expired → acquired (a dead owner is named in a
  /// printed warning); live → viewer mode; no store (or an unenforceable
  /// backend) → today's unleased behavior; publish/verify failure on an
  /// enforceable backend → LOUD refusal, returns false (#2138) — the
  /// caller must not let an unleased drive follow (boot aborts; an
  /// in-process switch restores the previous session via
  /// [_reclaimAfterSwitch]).
  Future<bool> _claimSessionLease() async {
    final store = config.leaseStore;
    final session = _session;
    if (store == null || session == null || _viewer != null) return true;
    final meta = await session.getMetadata();
    final result = await store.acquire(
      sessionFilePath: meta.path,
      sessionId: meta.id,
      host: 'cli',
      bootId: _leaseBootId,
      pid: config.processId ?? 0,
      sessionName: await session.getSessionName(),
    );

    switch (result) {
      case LeaseAcquired(:final replaced):
        _heldLeasePath = meta.path;
        if (replaced != null) {
          io.writeln(
            tuiWarning(
              'lease: previous owner ${leaseOwnerLabel(replaced.host)} '
              '(pid ${replaced.pid}) looks dead (stale) — driving fresh',
            ),
          );
        }
      case LeaseBlocked(:final lease):
        await _enterViewerMode(lease: lease, meta: meta);
      case LeaseUnenforced():
        // E5 fail-open: a backend WITHOUT atomic rename never blocks
        // opening a session — drive without enforcement.
        break;
      case LeaseRefused(:final reason):
        // #2138: the store could not prove the session free on an
        // enforceable backend — a second writer may be live. Refuse the
        // drive loudly; the caller owns the no-unleased-drive follow-up.
        io.writeln(
          tuiError(
            'lease: cannot prove this session is free (${reason.name}) — '
            'the lease store failed to publish/verify; refusing to drive. '
            'Fix the store (or clear a stale .owner.json) and reopen.',
          ),
        );
        return false;
    }
    return true;
  }

  /// Boot gate (#2138): a refused claim aborts the boot loudly — the
  /// process dies before anything can drive unleased (gh-1197 policy).
  Future<void> _requireLeaseClaim() async {
    if (!await _claimSessionLease()) {
      throw StateError(
        'session lease refused — the lease store cannot prove the '
        'session is free; refusing to drive',
      );
    }
  }

  /// Re-claims the lease after an in-process session switch (/reset,
  /// /session). A refused claim (#2138) restores [previousSession] and
  /// re-claims its just-released lease — no unleased drive may follow
  /// the error panel. If even the restore refuses, the store cannot
  /// enforce ownership at all: the CLI prints the loud refusal and stops
  /// CLEANLY (the contained-submit boundary swallows throws by design —
  /// a thrown StateError would silently resume driving a session the
  /// store cannot lease; stopping cannot).
  Future<void> _reclaimAfterSwitch(Session? previousSession) async {
    await _releaseSessionLease();
    if (await _claimSessionLease()) return;
    if (previousSession != null) {
      _session = previousSession;
      _notifyPluginSessionReady();
      _syncMailboxPrefix();
      _herdrSessionSwitched();
      if (await _claimSessionLease()) {
        io.writeln(
          tuiWarning(
            'lease: the new session could not be claimed — staying on the '
            'previous session',
          ),
        );
        return;
      }
    }
    io.writeln(
      tuiError(
        'lease: cannot enforce session ownership — the store refuses '
        'every publish/verify; the CLI stops rather than drive unleased. '
        'Fix the store and reopen.',
      ),
    );
    _exited = true;
  }

  /// Headless claim (E7): no viewer mode exists here. Acquired → the run
  /// drives; blocked → the owner's live lease (banner + exit 3);
  /// refused → [HeadlessLeaseClaimRefused] (loud note + exit 4, #2138) —
  /// never a throw into the crash handler, never an unleased drive.
  Future<HeadlessLeaseClaim> _claimSessionLeaseHeadless() async {
    final store = config.leaseStore;
    final session = _session;
    if (store == null || session == null) {
      return const HeadlessLeaseClaimAcquired();
    }
    final meta = await session.getMetadata();
    final result = await store.acquire(
      sessionFilePath: meta.path,
      sessionId: meta.id,
      host: 'cli',
      bootId: _leaseBootId,
      pid: config.processId ?? 0,
      sessionName: await session.getSessionName(),
    );
    switch (result) {
      case LeaseAcquired():
        _heldLeasePath = meta.path;
        return const HeadlessLeaseClaimAcquired();
      case LeaseBlocked(:final lease):
        return HeadlessLeaseClaimBlocked(lease);
      case LeaseUnenforced():
        return const HeadlessLeaseClaimAcquired();
      case LeaseRefused(:final reason):
        return HeadlessLeaseClaimRefused(reason);
    }
  }

  /// Resolves the headless/wire-serve lease gate (#428 + #2138):
  /// acquired → null (the run drives on); blocked → exit code 3 with the
  /// owner banner; refused → exit code 4 with the loud note. A non-null
  /// result is the process exit code — the run must stop with it.
  Future<int?> _resolveHeadlessLeaseGate() async {
    final claim = await _claimSessionLeaseHeadless();
    switch (claim) {
      case HeadlessLeaseClaimAcquired():
        return null;
      case HeadlessLeaseClaimBlocked(:final lease):
        io.writeln(viewerBannerText(lease, stale: false));
        return 3;
      case HeadlessLeaseClaimRefused(:final reason):
        io.writeln(
          tuiError(
            'lease: cannot prove this session is free (${reason.name}) — '
            'refusing to drive (exit 4)',
          ),
        );
        return 4;
    }
  }

  /// This instance becomes a viewer: tail the transcript, route composed
  /// input to the owner's mailbox. Prints nothing here — the REPLs print
  /// the banner after their own banner ([_printViewerBannerIfAny]).
  Future<void> _enterViewerMode({
    required SessionLease lease,
    required SessionMetadata meta,
  }) async {
    final attachment = _ViewerAttachment(
      sessionId: meta.id,
      sessionPath: meta.path,
      lease: lease,
      inputChannel: FileSessionInputChannel(
        repository: FileMessagingRepository(env: _env, root: _messagesRoot),
        fromId: 'fa CLI user',
      ),
      eventSource: FileSessionEventSource(
        env: _env,
        resolvePath: (_) async => meta.path,
      ),
    );
    _viewer = attachment;
    attachment.subscription = attachment.eventSource
        .watch(meta.id)
        .listen(_onViewerRows);
  }

  /// Tail rows: the first event is the pre-open backlog (printed dimmed,
  /// capped — the transcript already lives in the session file); every
  /// later event is live content from the driving host.
  void _onViewerRows(AttachedSessionEvent event) =>
      _renderViewerRows(_viewer, event.appended);

  void _renderViewerRows(
    _ViewerAttachment? viewer,
    List<AttachedMessage> appended,
  ) {
    if (viewer == null) return;
    final (rows, caption) = viewerBacklogSlice(appended, viewer.sawBacklog);
    viewer.sawBacklog = true;
    if (caption != null) io.writeln(_style.dim(caption));
    for (final row in rows) {
      _printViewerRow(row, dimmed: caption != null);
    }
  }

  void _printViewerRow(AttachedMessage row, {bool dimmed = false}) {
    final text = viewerRowText(row);
    if (dimmed) {
      io.writeln(_style.dim(text));
    } else if (row.role == AttachedMessageRole.user) {
      io.writeln(_style.bold(text));
    } else {
      io.writeln(text);
    }
  }

  /// The 2s viewer tick: follow the lease only — the owner's mail,
  /// presence, and orphan reclaims are theirs, never a viewer's job.
  /// A live→stale flip prints the reopen notice once.
